    36   *
    37   * Note that this function produces different key for the
    38   * NULL password, and for the password with zero length.
    39   */
    40  int
    41  _gnutls_pkcs12_string_to_key(const mac_entry_st * me,
    42                               unsigned int id, const uint8_t * salt,
    43                               unsigned int salt_size, unsigned int iter,
    44                               const char *pw, unsigned int req_keylen,
    45                               uint8_t * keybuf)
    46  {
    47          int rc;
    48          unsigned int i, j;
    49          digest_hd_st md;
    50          bigint_t num_b1 = NULL, num_ij = NULL;
    51          bigint_t v_mpi = NULL;
    52          unsigned int pwlen;
    53          uint8_t hash[MAX_HASH_SIZE], buf_b[MAX_V_SIZE], buf_i[MAX_PASS_LEN + MAX_V_SIZE], *p;
    54          uint8_t d[MAX_V_SIZE];
    55          size_t cur_keylen;
    56          size_t n, m, plen, i_size;
    57          size_t slen;
    58          gnutls_datum_t ucs2 = {NULL, 0};
    59          unsigned mac_len;
    60          uint8_t v_val[MAX_V_SIZE+1];
    61          unsigned v_size = 0;
    62
    63          switch (me->id) {
    64                  case GNUTLS_DIG_GOSTR_94:
    65                          v_size = 32;
    66                          break;
    67                  case GNUTLS_DIG_SHA1:
    68                  case GNUTLS_DIG_SHA224:
    69                  case GNUTLS_DIG_SHA256:
    70                  case GNUTLS_DIG_STREEBOG_256:
    71                  case GNUTLS_DIG_STREEBOG_512:
    72                          v_size = 64;
    73                          break;
    74                  case GNUTLS_DIG_SHA384:
    75                  case GNUTLS_DIG_SHA512:
    76                          v_size = 128;
    77                          break;
    78                  default:
    79                          break;
    80          }
    81
    82          if (v_size == 0 || v_size > MAX_V_SIZE)
    83                  return gnutls_assert_val(GNUTLS_E_UNIMPLEMENTED_FEATURE);
    84
    85          memset(v_val, 0, sizeof(v_val));
    86          v_val[0] = 0x01; /* make it be 2^64 or 2^128 */
    87
    88          cur_keylen = 0;
    89
    90          if (pw) {
    91                  pwlen = strlen(pw);
    92
    93                  if (pwlen == 0) {
    94                          ucs2.data = gnutls_calloc(1, 2);
    95                          if (ucs2.data == NULL)
    96                                  return gnutls_assert_val(GNUTLS_E_MEMORY_ERROR);
    97                          ucs2.size = 2;
    98                  } else {
    99                          rc = _gnutls_utf8_to_ucs2(pw, pwlen, &ucs2, 1);
   100                          if (rc < 0)
   101                                  return gnutls_assert_val(rc);
   102
   103                          /* include terminating zero */
   104                          ucs2.size+=2;
   105                  }
   106                  pwlen = ucs2.size;
   107                  pw = (char*)ucs2.data;
   108          } else {
   109                  pwlen = 0;
   110          }
   111
   112          if (pwlen > MAX_PASS_LEN) {
   113                  rc = gnutls_assert_val(GNUTLS_E_INVALID_REQUEST);
   114                  goto cleanup;
   115          }
   116
   117          rc = _gnutls_mpi_init_scan(&v_mpi, v_val, v_size+1);
   118          if (rc < 0) {
   119                  gnutls_assert();
   120                  goto cleanup;
   121          }
   122
   123          /* Store salt and password in BUF_I */
   124          slen = ((salt_size+v_size-1)/v_size) * v_size;
   125          plen = ((pwlen+v_size-1)/v_size) * v_size;
   126          i_size = slen + plen;
   127
   128          if (i_size > sizeof(buf_i)) {
   129                  rc = gnutls_assert_val(GNUTLS_E_INVALID_REQUEST);
   130                  goto cleanup;
   131          }
   132
   133          p = buf_i;
   134          for (i = 0; i < slen; i++)
   135                  *p++ = salt[i % salt_size];
   136
   137          if (pw) {
   138                  for (i = j = 0; i < plen; i += 2) {
   139                          *p++ = pw[j];
   140                          *p++ = pw[j+1];
   141                          j+=2;
   142                          if (j >= pwlen)
   143                                  j = 0;
   144                  }
   145          } else {
   146                  memset(p, 0, plen);
   147          }
   148
   149          mac_len = _gnutls_mac_get_algo_len(me);
   150          assert(mac_len != 0);
   151
   152          for (;;) {
   153                  rc = _gnutls_hash_init(&md, me);
   154                  if (rc < 0) {
   155                          gnutls_assert();
   156                          goto cleanup;
   157                  }
   158                  memset(d, id & 0xff, v_size);
   159                  _gnutls_hash(&md, d, v_size);
   160                  _gnutls_hash(&md, buf_i, i_size);
   161                  _gnutls_hash_deinit(&md, hash);
   162                  for (i = 1; i < iter; i++) {
   163                          rc = _gnutls_hash_fast((gnutls_digest_algorithm_t)me->id,
   164                                                 hash, mac_len, hash);
   165                          if (rc < 0) {
   166                                  gnutls_assert();
   167                                  goto cleanup;
   168                          }
   169                  }
   170                  for (i = 0; i < mac_len && cur_keylen < req_keylen; i++)
   171                          keybuf[cur_keylen++] = hash[i];
   172                  if (cur_keylen == req_keylen) {
   173                          rc = 0; /* ready */
   174                          goto cleanup;
   175                  }
   176
   177                  /* need more bytes. */
   178                  for (i = 0; i < v_size; i++)
   179                          buf_b[i] = hash[i % mac_len];
   180                  n = v_size;
   181                  rc = _gnutls_mpi_init_scan(&num_b1, buf_b, n);
   182                  if (rc < 0) {
   183                          gnutls_assert();
   184                          goto cleanup;
   185                  }
   186
   187                  rc = _gnutls_mpi_add_ui(num_b1, num_b1, 1);
   188                  if (rc < 0) {
   189                          gnutls_assert();
   190                          goto cleanup;
   191                  }
   192
   193                  for (i = 0; i < i_size; i += v_size) {
   194                          n = v_size;
   195                          rc = _gnutls_mpi_init_scan(&num_ij, buf_i + i, n);
   196                          if (rc < 0) {
   197                                  gnutls_assert();
   198                                  goto cleanup;
   199                          }
   200
   201                          rc = _gnutls_mpi_addm(num_ij, num_ij, num_b1, v_mpi);
   202                          if (rc < 0) {
   203                                  gnutls_assert();
   204                                  goto cleanup;
   205                          }
   206
   207                          n = v_size;
   208                          m = (_gnutls_mpi_get_nbits(num_ij) + 7) / 8;
   209
   210                          memset(buf_i + i, 0, n - m);
   211                          rc = _gnutls_mpi_print(num_ij, buf_i + i + n - m,
   212                                                 &n);
   213                          if (rc < 0) {
   214                                  gnutls_assert();
   215                                  goto cleanup;
   216                          }
   217                          _gnutls_mpi_release(&num_ij);
   218                  }
   219          }
   220        cleanup:
  1040
  1041                  *schema = p->schema;
  1042                  return 0;
  1043          } else if (*schema == PBES1_DES_MD5) {
  1044                  return _gnutls_read_pbkdf1_params(data, data_size, kdf_params,
  1045                                                    enc_params);
  1046          } else {                /* PKCS #12 schema */
  1047                  memset(enc_params, 0, sizeof(*enc_params));
  1048
  1049                  p = _gnutls_pkcs_schema_get(*schema);
  1050                  if (p == NULL) {
  1051                          gnutls_assert();
  1052                          result = GNUTLS_E_UNKNOWN_CIPHER_TYPE;
  1053                          goto error;
  1054                  }
  1055                  enc_params->cipher = p->cipher;
  1056                  enc_params->iv_size = gnutls_cipher_get_iv_size(p->cipher);
  1057
  1058                  if ((result =
  1059                       asn1_create_element(_gnutls_get_pkix(),
  1060                                           "PKIX1.pkcs-12-PbeParams",
  1061                                           &pasn)) != ASN1_SUCCESS) {
  1062                          gnutls_assert();
  1063                          result = _gnutls_asn2err(result);
  1064                          goto error;
  1065                  }
  1066
  1067                  /* Decode the parameters.
  1068                   */
  1069                  result = _asn1_strict_der_decode(&pasn, data, data_size, NULL);
  1070                  if (result != ASN1_SUCCESS) {
  1071                          gnutls_assert();
  1072                          result = _gnutls_asn2err(result);
  1073                          goto error;
  1074                  }
  1075
  1076                  result = read_pkcs12_kdf_params(pasn, kdf_params);
  1077                  if (result < 0) {
  1078                          gnutls_assert();
  1079                          goto error;
  1080                  }
  1081
  1082                  if (enc_params->iv_size) {
  1083                          result =
  1084                              _gnutls_pkcs12_string_to_key(mac_to_entry
  1085                                                           (GNUTLS_MAC_SHA1),
  1086                                                           2 /*IV*/,
  1087                                                           kdf_params->salt,
  1088                                                           kdf_params->salt_size,
  1089                                                           kdf_params->iter_count,
  1090                                                           password,
  1091                                                           enc_params->iv_size,
  1092                                                           enc_params->iv);
  1093                          if (result < 0) {
  1094                                  gnutls_assert();
  1095                                  goto error;
  1096                          }
  1097
  1098                  }
  1099
  1100                  asn1_delete_structure(&pasn);
  1101
  1102                  return 0;
  1103          }                       /* switch */
  1104
  1105   error:
  1106          asn1_delete_structure(&pasn);
  1107          return result;
  1108  }
