  1110  static int
  1111  _gnutls_pbes2_string_to_key(unsigned int pass_len, const char *password,
  1112                              const struct pbkdf2_params *kdf_params,
  1113                              int key_size, uint8_t *key)
  1114  {
  1115          int result = 0;
  1116
  1117          if (kdf_params->mac == GNUTLS_MAC_SHA1)
  1118                  pbkdf2_hmac_sha1(pass_len, (uint8_t *) password,
  1119                                   kdf_params->iter_count,
  1120                                   kdf_params->salt_size,
  1121                                   kdf_params->salt, key_size, key);
  1122          else if (kdf_params->mac == GNUTLS_MAC_SHA256)
  1123                  pbkdf2_hmac_sha256(pass_len, (uint8_t *) password,
  1124                                     kdf_params->iter_count,
  1125                                     kdf_params->salt_size,
  1126                                     kdf_params->salt, key_size, key);
  1127  #if ENABLE_GOST
  1128          else if (kdf_params->mac == GNUTLS_MAC_GOSTR_94)
  1129                  pbkdf2_hmac_gosthash94cp(pass_len, (uint8_t *) password,
  1130                                           kdf_params->iter_count,
  1131                                           kdf_params->salt_size,
  1132                                           kdf_params->salt, key_size, key);
  1133          else if (kdf_params->mac == GNUTLS_MAC_STREEBOG_256)
  1134                  pbkdf2_hmac_streebog256(pass_len, (uint8_t *) password,
  1135                                          kdf_params->iter_count,
  1136                                          kdf_params->salt_size,
  1137                                          kdf_params->salt, key_size, key);
  1138          else if (kdf_params->mac == GNUTLS_MAC_STREEBOG_512)
  1139                  pbkdf2_hmac_streebog512(pass_len, (uint8_t *) password,
  1140                                          kdf_params->iter_count,
  1141                                          kdf_params->salt_size,
  1142                                          kdf_params->salt, key_size, key);
  1143  #endif
  1144          else
  1145                  result =
  1146                      gnutls_assert_val(GNUTLS_E_UNKNOWN_HASH_ALGORITHM);
  1147
  1148          return result;
  1149  }
