  1151  int
  1152  _gnutls_pkcs_raw_decrypt_data(schema_id schema, ASN1_TYPE pkcs8_asn,
  1153                                const char *root, const char *_password,
  1154                                const struct pbkdf2_params *kdf_params,
  1155                                const struct pbe_enc_params *enc_params,
  1156                                gnutls_datum_t * decrypted_data)
  1157  {
  1158          gnutls_datum_t enc = { NULL, 0 };
  1159          uint8_t *key = NULL;
  1160          gnutls_datum_t dkey, d_iv;
  1161          cipher_hd_st ch;
  1162          int ch_init = 0;
  1163          int key_size, ret;
  1164          unsigned int pass_len = 0;
  1165          const struct pkcs_cipher_schema_st *p;
  1166          unsigned block_size;
  1167          const cipher_entry_st *ce;
  1168          char *password;
  1169
  1170          if (_password) {
  1171                  gnutls_datum_t pout;
  1172                  ret = _gnutls_utf8_password_normalize(_password, strlen(_password), &pout, 1);
  1173                  if (ret < 0)
  1174                          return gnutls_assert_val(ret);
  1175
  1176                  password = (char*)pout.data;
  1177                  pass_len = pout.size;
  1178          } else {
  1179                  password = NULL;
  1180                  pass_len = 0;
  1181          }
  1182
  1183          ret = _gnutls_x509_read_value(pkcs8_asn, root, &enc);
  1184          if (ret < 0) {
  1185                  gnutls_assert();
  1186                  enc.data = NULL;
  1187                  goto cleanup;
  1188          }
  1189
  1190          if (schema == PBES1_DES_MD5) {
  1191                  ret = _gnutls_decrypt_pbes1_des_md5_data(password, pass_len,
  1192                                                            kdf_params,
  1193                                                            enc_params, &enc,
  1194                                                            decrypted_data);
  1195                  if (ret < 0)
  1196                          goto error;
  1197                  goto cleanup;
  1198          }
  1199
  1200          if (kdf_params->key_size == 0) {
  1201                  key_size = gnutls_cipher_get_key_size(enc_params->cipher);
  1202          } else
  1203                  key_size = kdf_params->key_size;
  1204
  1205          key = gnutls_malloc(key_size);
  1206          if (key == NULL) {
  1207                  gnutls_assert();
  1208                  ret = GNUTLS_E_MEMORY_ERROR;
  1209                  goto error;
  1210          }
  1211
  1212          /* generate the key
  1213           */
  1214          p = _gnutls_pkcs_schema_get(schema);
  1215          if (p != NULL && p->pbes2 != 0) {       /* PBES2 */
  1216                  ret = _gnutls_pbes2_string_to_key(pass_len, password,
  1217                                                       kdf_params,
  1218                                                       key_size, key);
  1219                  if (ret < 0) {
  1220                          gnutls_assert();
  1221                          goto error;
  1222                  }
  1223          } else if (p != NULL) { /* PKCS 12 schema */
  1224                  ret =
  1225                      _gnutls_pkcs12_string_to_key(mac_to_entry(GNUTLS_MAC_SHA1),
  1226                                                   1 /*KEY*/,
  1227                                                   kdf_params->salt,
  1228                                                   kdf_params->salt_size,
  1229                                                   kdf_params->iter_count,
  1230                                                   password, key_size, key);
  1231
  1232                  if (ret < 0) {
  1233                          gnutls_assert();
  1234                          goto error;
  1235                  }
  1236          } else {
  1237                  gnutls_assert();
  1238                  ret = GNUTLS_E_UNKNOWN_CIPHER_TYPE;
  1239                  goto error;
  1240          }
  1241
  1242          ce = cipher_to_entry(enc_params->cipher);
  1243          block_size = _gnutls_cipher_get_block_size(ce);
  1244
  1245          if (ce->type == CIPHER_BLOCK) {
  1246                  if (enc.size % block_size != 0 || (unsigned)enc_params->iv_size != block_size) {
  1247                          gnutls_assert();
  1248                          ret = GNUTLS_E_DECRYPTION_FAILED;
  1249                          goto error;
  1250                  }
